"use strict";(self.webpackChunkeleutherius_blog=self.webpackChunkeleutherius_blog||[]).push([[8130],{7735:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"2025-05-25-docker-multistage-build","metadata":{"permalink":"/blog/2025-05-25-docker-multistage-build","source":"@site/blog/2025/05/25/docker-multistage-build.md","title":"Docker Multi-stage Build \uc774\ud574\uc640 \ud65c\uc6a9","description":"\ub3c4\ucee4 \uc774\ubbf8\uc9c0\ub97c \ub9cc\ub4e4\ub2e4 \ubcf4\uba74 \ube4c\ub4dc \ud658\uacbd\uacfc \uc2e4\ud589 \ud658\uacbd\uc744 \ubd84\ub9ac\ud558\uace0 \uc2f6\uc5b4\uc9c8 \ub54c\uac00 \uc788\uc2b5\ub2c8\ub2e4.","date":"2025-05-25T00:00:00.000Z","tags":[{"inline":true,"label":"docker","permalink":"/blog/tags/docker"},{"inline":true,"label":"build","permalink":"/blog/tags/build"},{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"optimization","permalink":"/blog/tags/optimization"}],"readingTime":3.24,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2025-05-25-docker-multistage-build","title":"Docker Multi-stage Build \uc774\ud574\uc640 \ud65c\uc6a9","authors":["eleutherius"],"tags":["docker","build","devops","optimization"]},"unlisted":false,"nextItem":{"title":"Java 8\ubd80\ud130 25\uae4c\uc9c0 LTS \ubc0f \uc8fc\uc694 \uae30\ub2a5 \uc694\uc57d (\uc608\uc81c \ud3ec\ud568)","permalink":"/blog/2025-05-25-java-version-summary"}},"content":"\ub3c4\ucee4 \uc774\ubbf8\uc9c0\ub97c \ub9cc\ub4e4\ub2e4 \ubcf4\uba74 `\ube4c\ub4dc \ud658\uacbd`\uacfc `\uc2e4\ud589 \ud658\uacbd`\uc744 \ubd84\ub9ac\ud558\uace0 \uc2f6\uc5b4\uc9c8 \ub54c\uac00 \uc788\uc2b5\ub2c8\ub2e4.  \\n\uc774\ub54c \uc720\uc6a9\ud55c \uae30\ub2a5\uc774 \ubc14\ub85c **Multi-stage Build**\uc785\ub2c8\ub2e4. \uc774 \ud3ec\uc2a4\ud2b8\uc5d0\uc11c\ub294 Multi-stage\uc758 \uac1c\ub150\ubd80\ud130 \uc2e4\uc804 \uc608\uc2dc, \uc7a5\uc810\uae4c\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uc65c Multi-stage Build\uac00 \ud544\uc694\ud55c\uac00?\\n\\n\uae30\uc874 Dockerfile\uc5d0\uc11c\ub294 \uc571\uc744 \ube4c\ub4dc\ud558\uae30 \uc704\ud55c \uc885\uc18d\uc131\uacfc \uc2e4\ud589\uc744 \uc704\ud55c \ud658\uacbd\uc774 \ud55c \uc774\ubbf8\uc9c0 \uc548\uc5d0 \ud3ec\ud568\ub418\uace4 \ud588\uc2b5\ub2c8\ub2e4. \uc774\ub85c \uc778\ud574:\\n\\n- **\uc774\ubbf8\uc9c0 \ud06c\uae30\uac00 \ucee4\uc9c0\uace0**\\n- **\ubcf4\uc548 \ucde8\uc57d\uc810 \ub178\ucd9c \ubc94\uc704\uac00 \ub113\uc5b4\uc9c0\uba70**\\n- **\uc2e4\ud589\uc5d0 \ubd88\ud544\uc694\ud55c \ud30c\uc77c\uc774 \ud568\uaed8 \ubc30\ud3ec\ub418\ub294** \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.\\n\\nMulti-stage Build\ub294 \uc774 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \ub4f1\uc7a5\ud55c \uae30\ub2a5\uc785\ub2c8\ub2e4.  \\n**\ud558\ub098\uc758 Dockerfile \uc548\uc5d0\uc11c \uc5ec\ub7ec \uac1c\uc758 \uc774\ubbf8\uc9c0 \ub2e8\uacc4\ub97c \uc815\uc758\ud558\uace0, \ud544\uc694\ud55c \uc0b0\ucd9c\ubb3c\ub9cc \ucd94\ucd9c\ud558\uc5ec \ucd5c\uc885 \uc774\ubbf8\uc9c0\uc5d0 \ud3ec\ud568**\uc2dc\ud0ac \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n---\\n\\n## \uae30\ubcf8 \uc608\uc2dc: Node.js + TypeScript \ud504\ub85c\uc81d\ud2b8\\n\\n```Dockerfile\\n# 1\ub2e8\uacc4: \ube4c\ub4dc \ud658\uacbd\\nFROM node:18-alpine AS builder\\nWORKDIR /app\\nCOPY package*.json ./\\nRUN npm ci\\nCOPY . .\\nRUN npm run build\\n\\n# 2\ub2e8\uacc4: \uc2e4\ud589 \ud658\uacbd\\nFROM node:18-alpine\\nWORKDIR /app\\nCOPY --from=builder /app/dist ./dist\\nCOPY --from=builder /app/package*.json ./\\nRUN npm ci --omit=dev\\nCMD [\\"node\\", \\"dist/index.js\\"]\\n```\\n\\n### \uc124\uba85\\n\\n| \uad6c\ubd84 | \ub0b4\uc6a9 |\\n|------|------|\\n| `AS builder` | \ube4c\ub4dc \ub2e8\uacc4\ub97c \ubcc4\uce6d\uc73c\ub85c \uc9c0\uc815 |\\n| `COPY --from=builder` | \ube4c\ub4dc \ub2e8\uacc4\uc5d0\uc11c \uc0b0\ucd9c\ubb3c\ub9cc \uac00\uc838\uc634 |\\n| `npm ci --omit=dev` | \uc2e4\ud589\uc5d0 \ubd88\ud544\uc694\ud55c devDependencies \uc81c\uac70 |\\n\\n---\\n\\n## \uc7a5\uc810\\n\\n- \u2705 **\uc774\ubbf8\uc9c0 \ud06c\uae30 \uac10\uc18c**  \\n  \ube4c\ub4dc \ub3c4\uad6c, \ud14c\uc2a4\ud2b8 \ub3c4\uad6c \ub4f1\uc740 \ucd5c\uc885 \uc774\ubbf8\uc9c0\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc74c\\n\\n- \u2705 **\ubcf4\uc548\uc131 \ud5a5\uc0c1**  \\n  \uc2e4\ud589 \ud658\uacbd\uc744 \ucd5c\uc18c\ud654\ud568\uc73c\ub85c\uc368 \uacf5\uaca9 \ud45c\uba74 \ucd95\uc18c\\n\\n- \u2705 **\ube4c\ub4dc \uc18d\ub3c4 \uac1c\uc120**  \\n  \uce90\uc2dc \ud65c\uc6a9\uc774 \ub354 \ud6a8\uc728\uc801\\n\\n---\\n\\n## \uace0\uae09 \uc608\uc2dc: Go \uc5b8\uc5b4 \ud504\ub85c\uc81d\ud2b8\\n\\n```Dockerfile\\nFROM golang:1.20 AS builder\\nWORKDIR /src\\nCOPY . .\\nRUN go build -o app .\\n\\nFROM alpine\\nCOPY --from=builder /src/app /app\\nENTRYPOINT [\\"/app\\"]\\n```\\n\\n> Go\ucc98\ub7fc \ubc14\uc774\ub108\ub9ac\ub9cc \ucd94\ucd9c \uac00\ub2a5\ud55c \uc5b8\uc5b4\ub294 \ub354\uc6b1 \uadf9\ub2e8\uc801\uc73c\ub85c \uc774\ubbf8\uc9c0 \ud06c\uae30\ub97c \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4 (\uc218 MB \uc218\uc900).\\n\\n---\\n\\n## \uc2e4\uc804 \ud301\\n\\n- **\uc911\uac04 \ub2e8\uacc4 \uce90\uc2dc \ud65c\uc6a9**\uc744 \uc704\ud574 `--target` \uc635\uc158\uc744 \ud65c\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- CI/CD\uc5d0\uc11c\ub294 **\uc911\uac04 \ube4c\ub4dc\uae4c\uc9c0 \ud14c\uc2a4\ud2b8**\ud55c \ud6c4 \ub9c8\uc9c0\ub9c9 \ub2e8\uacc4\ub85c \ub118\uc5b4\uac00\ub294 \uad6c\uc870\ub3c4 \ucd94\ucc9c\ub429\ub2c8\ub2e4.\\n- `COPY` \uc2dc \ubd88\ud544\uc694\ud55c \ud30c\uc77c\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub3c4\ub85d `.dockerignore` \uc124\uc815\ub3c4 \ubcd1\ud589\ud558\uc138\uc694.\\n\\n---\\n\\n## Reference\\n\\nexport const linkList = [\\n  {href: \\"https://docs.docker.com/build/building/multi-stage/\\", text: \\"Docker \uacf5\uc2dd \ubb38\uc11c - Multi-stage Builds\\"},\\n  {href: \\"https://docs.docker.com/develop/develop-images/multistage-build/\\", text: \\"Docker \uac1c\ubc1c\uc790 \uac00\uc774\ub4dc - Multistage Image\\"},\\n  {href: \\"https://12factor.net/\\", text: \\"The Twelve-Factor App (\uad00\ub828 \uac1c\ub150)\\"}\\n];\\n\\nimport ReferenceLink from \\"@site/src/components/ReferenceLink\\";\\n\\n<details>\\n  <summary>Reference</summary>\\n  <ReferenceLink linkList={linkList} />\\n</details>"},{"id":"2025-05-25-java-version-summary","metadata":{"permalink":"/blog/2025-05-25-java-version-summary","source":"@site/blog/2025/05/25/java-version-summary-with-code.md","title":"Java 8\ubd80\ud130 25\uae4c\uc9c0 LTS \ubc0f \uc8fc\uc694 \uae30\ub2a5 \uc694\uc57d (\uc608\uc81c \ud3ec\ud568)","description":"Java\ub294 \uc9c0\uc18d\uc801\uc778 \ub9b4\ub9ac\uc2a4\ub97c \ud1b5\ud574 \ub2e4\uc591\ud55c \uae30\ub2a5\uc744 \ub3c4\uc785\ud574\uc654\uc73c\uba70, \uadf8 \uc911 \uc77c\ubd80 \ubc84\uc804\uc740 LTS(\uc7a5\uae30 \uc9c0\uc6d0)\ub85c \uc9c0\uc815\ub418\uc5b4 \uc548\uc815\uc801\uc778 \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 Java 8\ubd80\ud130 25\uae4c\uc9c0\uc758 LTS \uc5ec\ubd80, \uc815\uc2dd \uae30\ub2a5 \uc911\uc2ec\uc758 \uc8fc\uc694 \ubcc0\ud654, EOL \uc815\ubcf4, \uadf8\ub9ac\uace0 \ubc84\uc804\ubcc4 \uc608\uc81c \ucf54\ub4dc\ub97c \ud568\uaed8 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2025-05-25T00:00:00.000Z","tags":[{"inline":true,"label":"java","permalink":"/blog/tags/java"},{"inline":true,"label":"version","permalink":"/blog/tags/version"},{"inline":true,"label":"lts","permalink":"/blog/tags/lts"},{"inline":true,"label":"jdk","permalink":"/blog/tags/jdk"},{"inline":true,"label":"roadmap","permalink":"/blog/tags/roadmap"}],"readingTime":3.08,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2025-05-25-java-version-summary","title":"Java 8\ubd80\ud130 25\uae4c\uc9c0 LTS \ubc0f \uc8fc\uc694 \uae30\ub2a5 \uc694\uc57d (\uc608\uc81c \ud3ec\ud568)","authors":["eleutherius"],"tags":["java","version","lts","jdk","roadmap"]},"unlisted":false,"prevItem":{"title":"Docker Multi-stage Build \uc774\ud574\uc640 \ud65c\uc6a9","permalink":"/blog/2025-05-25-docker-multistage-build"},"nextItem":{"title":"Spring WebFlux & Reactor \ucd08\uae09 \uac00\uc774\ub4dc","permalink":"/blog/2025-05-25-spring-webflux-intro"}},"content":"Java\ub294 \uc9c0\uc18d\uc801\uc778 \ub9b4\ub9ac\uc2a4\ub97c \ud1b5\ud574 \ub2e4\uc591\ud55c \uae30\ub2a5\uc744 \ub3c4\uc785\ud574\uc654\uc73c\uba70, \uadf8 \uc911 \uc77c\ubd80 \ubc84\uc804\uc740 LTS(\uc7a5\uae30 \uc9c0\uc6d0)\ub85c \uc9c0\uc815\ub418\uc5b4 \uc548\uc815\uc801\uc778 \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 **Java 8\ubd80\ud130 25\uae4c\uc9c0\uc758 LTS \uc5ec\ubd80, \uc815\uc2dd \uae30\ub2a5 \uc911\uc2ec\uc758 \uc8fc\uc694 \ubcc0\ud654, EOL \uc815\ubcf4**, \uadf8\ub9ac\uace0 **\ubc84\uc804\ubcc4 \uc608\uc81c \ucf54\ub4dc**\ub97c \ud568\uaed8 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ud83d\udcca Java \ubc84\uc804 \uc694\uc57d (Java 8 ~ Java 25)\\n\\n| \ubc84\uc804 | \ucd9c\uc2dc\uc77c | LTS | \uc8fc\uc694 \uae30\ub2a5 (\uc815\uc2dd \ub3c4\uc785 \uae30\uc900) | EOL (Oracle \uae30\uc900) |\\n|------|--------|------|---------------------------|--------------------|\\n| **Java 8** | 2014-03 | \u2705 | Lambda, Stream API, java.time, Optional | 2022-12 (\uacf5\uac1c) |\\n| **Java 9** | 2017-09 | \u274c | \ubaa8\ub4c8 \uc2dc\uc2a4\ud15c (JPMS), JShell | 2018-03 |\\n| **Java 10** | 2018-03 | \u274c | \uc9c0\uc5ed \ubcc0\uc218 \ud0c0\uc785 \ucd94\ub860 (`var`) | 2018-09 |\\n| **Java 11** | 2018-09 | \u2705 | HTTP Client, \uc0c8\ub85c\uc6b4 String/File API | 2026-09 |\\n| **Java 13** | 2019-09 | \u274c | \ud14d\uc2a4\ud2b8 \ube14\ub85d (\uc815\uc2dd\ud654 \uc2dc\uc791) | 2020-03 |\\n| **Java 16** | 2021-03 | \u274c | Records (\uc815\uc2dd), instanceof \ud328\ud134 \ub9e4\uce6d | 2021-09 |\\n| **Java 17** | 2021-09 | \u2705 | Sealed Classes, Switch \ud328\ud134 \ub9e4\uce6d | 2029-09 |\\n| **Java 18** | 2022-03 | \u274c | UTF-8 \uae30\ubcf8 \uc778\ucf54\ub529 | 2022-09 |\\n| **Java 21** | 2023-09 | \u2705 | Virtual Threads, Sequenced Collections | 2031-09 |\\n| **Java 24** | 2025-03 | \u274c | \uc8fc\uc694 \uc815\uc2dd \uae30\ub2a5 \uc815\ubcf4 \uc5c6\uc74c | 2025-09 \uc608\uc815 |\\n| **Java 25** | 2025-09 \uc608\uc815 | \u2705 | \uac12 \ud074\ub798\uc2a4(Value Classes, \uc608\uc815) | 2033-09 |\\n\\n---\\n\\n## \ud83e\uddea Java \uc8fc\uc694 \uae30\ub2a5 \uc608\uc81c\\n\\n### \u2705 Java 8 - Lambda & Stream API\\n\\n```java\\nList<String> names = Arrays.asList(\\"Kim\\", \\"Lee\\", \\"Park\\");\\nnames.stream().filter(n -> n.startsWith(\\"K\\")).forEach(System.out::println);\\n```\\n\\n---\\n\\n### \u2705 Java 9 - \ubaa8\ub4c8 \uc2dc\uc2a4\ud15c\\n\\n```java\\nmodule com.example.app {\\n    requires java.base;\\n}\\n```\\n\\n---\\n\\n### \u2705 Java 10 - var \uc9c0\uc5ed \ubcc0\uc218\\n\\n```java\\nvar message = \\"Hello, Java 10!\\";\\nSystem.out.println(message);\\n```\\n\\n---\\n\\n### \u2705 Java 11 - HTTP Client\\n\\n```java\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://example.com\\"))\\n    .build();\\nclient.sendAsync(request, HttpResponse.BodyHandlers.ofString())\\n    .thenAccept(System.out::println);\\n```\\n\\n---\\n\\n### \u2705 Java 13 - \ud14d\uc2a4\ud2b8 \ube14\ub85d\\n\\n```java\\nString html = \\"\\"\\"\\n<html>\\n  <body>Hello</body>\\n</html>\\n\\"\\"\\";\\nSystem.out.println(html);\\n```\\n\\n---\\n\\n### \u2705 Java 16 - Record\\n\\n```java\\npublic record User(String name, int age) {}\\nUser user = new User(\\"Alice\\", 30);\\nSystem.out.println(user.name());\\n```\\n\\n---\\n\\n### \u2705 Java 17 - Sealed Class\\n\\n```java\\npublic sealed class Shape permits Circle, Rectangle {}\\nfinal class Circle extends Shape {}\\nfinal class Rectangle extends Shape {}\\n```\\n\\n---\\n\\n### \u2705 Java 18 - UTF-8 \uae30\ubcf8 \uc778\ucf54\ub529\\n\\n```java\\nFiles.write(Path.of(\\"test.txt\\"), \\"\uc548\ub155\ud558\uc138\uc694\\".getBytes());\\n```\\n\\n---\\n\\n### \u2705 Java 21 - Virtual Threads\\n\\n```java\\nRunnable task = () -> System.out.println(\\"Running in \\" + Thread.currentThread());\\nThread.startVirtualThread(task);\\n```\\n\\n---\\n\\n## \u2705 \uc694\uc57d\\n\\n- **LTS \ubc84\uc804**: 8, 11, 17, 21, 25 (\uc608\uc815)\\n- **\uc608\uc81c \ud3ec\ud568 \ubc84\uc804\ubcc4 \uae30\ub2a5 \ube44\uad50 \uac00\ub2a5**\\n- **\ud504\ub9ac\ubdf0/\uc2e4\ud5d8 \uae30\ub2a5 \uc81c\uc678, \uc815\uc2dd \uae30\ub2a5 \uc911\uc2ec**\\n\\n---\\n\\n## \ud83d\udd17 \ucc38\uace0 \uc790\ub8cc\\n\\n- [Oracle Java SE \uc9c0\uc6d0 \ub85c\ub4dc\ub9f5](https://www.oracle.com/java/technologies/java-se-support-roadmap.html)\\n- [Java \ubc84\uc804 \ud788\uc2a4\ud1a0\ub9ac (Wikipedia)](https://en.wikipedia.org/wiki/Java_version_history)\\n- [OpenJDK JEP \ubaa9\ub85d](https://openjdk.org/jeps/0)"},{"id":"2025-05-25-spring-webflux-intro","metadata":{"permalink":"/blog/2025-05-25-spring-webflux-intro","source":"@site/blog/2025/05/25/spring-webflux-intro.md","title":"Spring WebFlux & Reactor \ucd08\uae09 \uac00\uc774\ub4dc","description":"Spring WebFlux\uc640 Reactor\ub294 \ube44\ub3d9\uae30 \ub17c\ube14\ub85c\ud0b9 \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \uac00\ub2a5\ud558\uac8c \ud574\uc8fc\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.","date":"2025-05-25T00:00:00.000Z","tags":[{"inline":true,"label":"spring","permalink":"/blog/tags/spring"},{"inline":true,"label":"webflux","permalink":"/blog/tags/webflux"},{"inline":true,"label":"reactor","permalink":"/blog/tags/reactor"},{"inline":true,"label":"java","permalink":"/blog/tags/java"},{"inline":true,"label":"reactive","permalink":"/blog/tags/reactive"}],"readingTime":3.22,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2025-05-25-spring-webflux-intro","title":"Spring WebFlux & Reactor \ucd08\uae09 \uac00\uc774\ub4dc","authors":["eleutherius"],"tags":["spring","webflux","reactor","java","reactive"]},"unlisted":false,"prevItem":{"title":"Java 8\ubd80\ud130 25\uae4c\uc9c0 LTS \ubc0f \uc8fc\uc694 \uae30\ub2a5 \uc694\uc57d (\uc608\uc81c \ud3ec\ud568)","permalink":"/blog/2025-05-25-java-version-summary"},"nextItem":{"title":"Collections in scala (2.x)","permalink":"/blog/2023-07-22-scala-collections"}},"content":"Spring WebFlux\uc640 Reactor\ub294 \ube44\ub3d9\uae30 \ub17c\ube14\ub85c\ud0b9 \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \uac00\ub2a5\ud558\uac8c \ud574\uc8fc\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.  \\n\uc774 \uae00\uc5d0\uc11c\ub294 \ucd08\uae09\uc790\ub4e4\uc774 \uc785\ubb38\ud558\uae30 \uc88b\uc740 4\uac00\uc9c0 \uc8fc\uc81c\ub97c \uc911\uc2ec\uc73c\ub85c \uac1c\ub150\uacfc \uc2e4\uc804 \uc608\uc2dc\ub97c \ud568\uaed8 \uc18c\uac1c\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n---\\n\\n## 1. Spring WebFlux\ub780 \ubb34\uc5c7\uc778\uac00?\\n\\nSpring WebFlux\ub294 Spring 5\ubd80\ud130 \ub3c4\uc785\ub41c **\ube44\ub3d9\uae30 \ub17c\ube14\ub85c\ud0b9 \uc6f9 \ud504\ub808\uc784\uc6cc\ud06c**\uc785\ub2c8\ub2e4. \uc804\ud1b5\uc801\uc778 `Spring MVC`\ub294 \uc11c\ube14\ub9bf \uae30\ubc18\uc73c\ub85c **\ube14\ub85c\ud0b9 I/O**\ub97c \uc0ac\uc6a9\ud558\uc9c0\ub9cc, WebFlux\ub294 **Reactor \uae30\ubc18\uc758 \ub17c\ube14\ub85c\ud0b9 \ucc98\ub9ac \ubaa8\ub378**\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n### \uc8fc\uc694 \ucc28\uc774\uc810\\n\\n| \ud56d\ubaa9 | Spring MVC | Spring WebFlux |\\n|------|------------|----------------|\\n| \uc2e4\ud589 \ubaa8\ub378 | \uc11c\ube14\ub9bf (Servlet API) | Netty (\uae30\ubcf8) |\\n| I/O \ubc29\uc2dd | \ube14\ub85c\ud0b9 (Blocking) | \ub17c\ube14\ub85c\ud0b9 (Non-blocking) |\\n| \uc2a4\ub808\ub4dc \uc0ac\uc6a9 | \uc694\uccad\ub2f9 \ud558\ub098\uc758 \uc2a4\ub808\ub4dc | \uc774\ubca4\ud2b8 \ub8e8\ud504 \uae30\ubc18 |\\n| \ubc18\ud658 \ud0c0\uc785 | `String`, `ModelAndView` \ub4f1 | `Mono`, `Flux` |\\n\\n### \uc5b8\uc81c WebFlux\ub97c \uc0ac\uc6a9\ud560\uae4c?\\n\\n- \ub3d9\uc2dc\uc5d0 \uc218\ucc9c \uac1c\uc758 \uc694\uccad\uc744 \ucc98\ub9ac\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\\n- \ube44\ub3d9\uae30 \ucc98\ub9ac\uc640 \uc2a4\ud2b8\ub9ac\ubc0d\uc774 \ud544\uc694\ud55c \uacbd\uc6b0 (\uc608: SSE, WebSocket)\\n- \ub9ac\uc18c\uc2a4\uac00 \uc81c\ud55c\ub41c \ud658\uacbd (IoT \ub4f1)\uc5d0\uc11c\uc758 \uace0\uc131\ub2a5 \uc11c\ubc84\\n\\n---\\n\\n## 2. Mono\uc640 Flux \uae30\ucd08\\n\\nReactor\uc5d0\uc11c\ub294 \ube44\ub3d9\uae30 \ub370\uc774\ud130 \ud750\ub984\uc744 **`Mono`** (0~1\uac1c) \ub610\ub294 **`Flux`** (0~N\uac1c)\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n\\n### \uae30\ubcf8 \uac1c\ub150\\n\\n```java\\nMono<String> mono = Mono.just(\\"Hello Mono\\");\\nFlux<Integer> flux = Flux.just(1, 2, 3, 4, 5);\\n```\\n\\n### \uc8fc\uc694 \uc5f0\uc0b0\uc790\\n\\n| \uc5f0\uc0b0\uc790 | \uc124\uba85 |\\n|--------|------|\\n| `map()` | \ubcc0\ud658 |\\n| `flatMap()` | \ube44\ub3d9\uae30 \ub0b4\ubd80 \ud750\ub984 \ubcd1\ud569 |\\n| `filter()` | \uc870\uac74 \ud544\ud130\ub9c1 |\\n| `zip()` | \uc5ec\ub7ec \uc2a4\ud2b8\ub9bc \ud569\uce58\uae30 |\\n| `onErrorResume()` | \uc608\uc678 \ucc98\ub9ac |\\n\\n### \uc2e4\ud589\\n\\n```java\\nmono.subscribe(System.out::println);\\nflux.subscribe(i -> System.out.println(\\"Value: \\" + i));\\n```\\n\\n---\\n\\n## 3. WebClient \uae30\ubcf8 \uc0ac\uc6a9\ubc95\\n\\nWebClient\ub294 WebFlux\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 **\ub17c\ube14\ub85c\ud0b9 HTTP \ud074\ub77c\uc774\uc5b8\ud2b8**\uc785\ub2c8\ub2e4. `RestTemplate`\ubcf4\ub2e4 \ub354 \uc720\uc5f0\ud558\uba70, Reactor \uae30\ubc18\uc73c\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4.\\n\\n### \uae30\ubcf8 \uc608\uc81c\\n\\n```java\\nWebClient webClient = WebClient.create(\\"https://jsonplaceholder.typicode.com\\");\\n\\nMono<String> response = webClient.get()\\n        .uri(\\"/todos/1\\")\\n        .retrieve()\\n        .bodyToMono(String.class);\\n\\nresponse.subscribe(System.out::println);\\n```\\n\\n### \uc8fc\uc694 \uae30\ub2a5\\n\\n- `retrieve()`: \uc751\ub2f5 \ucd94\ucd9c\\n- `exchangeToMono()`: \uc0c1\ud0dc \ucf54\ub4dc\ubcc4 \ubd84\uae30 \ucc98\ub9ac\\n- `timeout()`, `retry()` \ub4f1 \uace0\uae09 \uc5f0\uc0b0\uc790 \uc9c0\uc6d0\\n\\n---\\n\\n## 4. \uac04\ub2e8\ud55c \ube44\ub3d9\uae30 API \ub9cc\ub4e4\uae30 (WebFlux \uae30\ubc18)\\n\\nSpring WebFlux\ub97c \uc0ac\uc6a9\ud574 \ub2e4\uc74c\uacfc \uac19\uc740 REST API\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc608\uc81c\\n\\n```java\\n@RestController\\n@RequestMapping(\\"/api\\")\\npublic class HelloController {\\n\\n    @GetMapping(\\"/hello\\")\\n    public Mono<String> hello() {\\n        return Mono.just(\\"\uc548\ub155\ud558\uc138\uc694!\\");\\n    }\\n\\n    @GetMapping(\\"/numbers\\")\\n    public Flux<Integer> numbers() {\\n        return Flux.range(1, 5);\\n    }\\n}\\n```\\n\\n### \uc2e4\ud589 \uacb0\uacfc\\n\\n- `/api/hello` \u2192 `\\"\uc548\ub155\ud558\uc138\uc694!\\"` \ubc18\ud658\\n- `/api/numbers` \u2192 `1 2 3 4 5` \uc2a4\ud2b8\ub9ac\ubc0d\\n\\n---\\n\\n## Reference\\n\\nexport const linkList = [\\n  {href: \\"https://docs.spring.io/spring-framework/reference/web/webflux/new-framework.html\\", text: \\"Spring \uacf5\uc2dd \ubb38\uc11c - WebFlux\\"},\\n  {href: \\"https://projectreactor.io/docs/core/release/reference/\\", text: \\"Reactor \uacf5\uc2dd \ubb38\uc11c\\"},\\n  {href: \\"https://docs.spring.io/spring-framework/docs/current/javadoc-api/org/springframework/web/reactive/function/client/WebClient.html\\", text: \\"WebClient Javadoc\\"},\\n  {href: \\"https://www.baeldung.com/spring-webflux\\", text: \\"Baeldung - WebFlux \uc18c\uac1c\\"}\\n];\\n\\nimport ReferenceLink from \\"@site/src/components/ReferenceLink\\";\\n\\n<details>\\n  <summary>Reference</summary>\\n  <ReferenceLink linkList={linkList} />\\n</details>"},{"id":"2023-07-22-scala-collections","metadata":{"permalink":"/blog/2023-07-22-scala-collections","source":"@site/blog/2023/07/22/scala-collections.mdx","title":"Collections in scala (2.x)","description":"\uc2a4\uce7c\ub77c\uc758 Collections\uc740 Java\uc758 Collections\uc640 \uc720\uc0ac\ud558\uc9c0\ub9cc, \ubcf4\ub2e4 \uac04\uacb0\ud558\uace0 \ud45c\ud604\ub825\uc774 \ub192\uc740 API\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.","date":"2023-07-22T00:00:00.000Z","tags":[{"inline":false,"label":"scala","permalink":"/blog/tags/scala","description":"scala"},{"inline":false,"label":"language","permalink":"/blog/tags/language","description":"language"}],"readingTime":2.98,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2023-07-22-scala-collections","title":"Collections in scala (2.x)","authors":["eleutherius"],"tags":["scala","language"]},"unlisted":false,"prevItem":{"title":"Spring WebFlux & Reactor \ucd08\uae09 \uac00\uc774\ub4dc","permalink":"/blog/2025-05-25-spring-webflux-intro"},"nextItem":{"title":"MQTT \ud504\ub85c\ud1a0\ucf5c","permalink":"/blog/2023-03-05-mqtt-base"}},"content":"\uc2a4\uce7c\ub77c\uc758 Collections\uc740 Java\uc758 Collections\uc640 \uc720\uc0ac\ud558\uc9c0\ub9cc, \ubcf4\ub2e4 \uac04\uacb0\ud558\uace0 \ud45c\ud604\ub825\uc774 \ub192\uc740 API\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\uc2a4\uce7c\ub77c\uc758 Collections\ub294 \ubcc0\uacbd \ubd88\uac00\ub2a5\ud558\uba70, \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d \ud328\ub7ec\ub2e4\uc784\uacfc \uc798 \uc5b4\uc6b8\ub9ac\ub294 \uc790\ub8cc \uad6c\uc870\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uc815\ub9ac\\n| Class | Description|\\n| --- |-------------------------------------------|\\n| ArrayBuffer | an indexed, mutable sequence|\\n| List | a linear (linked list), immutable sequence|\\n| Vector | an indexed, immutable sequence|\\n| Map | the base Map (key/value pairs) class|\\n| Set | the base Set class|\\n\\n## ArrayBuffer\\n\\nArrayBuffer\ub294 \ubcc0\uacbd \uac00\ub2a5\ud55c \uc2dc\ud000\uc2a4\uc785\ub2c8\ub2e4. \ud06c\uae30\uac00 \uac00\ubcc0\uc801\uc774\ubbc0\ub85c, \uc0c8\ub85c\uc6b4 \uac12\uc744 \ucd94\uac00\ud558\uac70\ub098 \uc0ad\uc81c\ud558\ub294 \uac83\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n``` scala\\n// ArrayBuffer \uc0dd\uc131\\nval myBuffer = ArrayBuffer(1, 2, 3, 4, 5)\\n\\n// \uac12 \ucd94\uac00\\nmyBuffer += 6\\n\\n// \uac12 \uc81c\uac70\\nmyBuffer -= 3\\n\\n// \uac12 \uc870\ud68c\\nmyBuffer(2) // 4\\n```\\n\\n## List\\n\\nList\ub294 \ubcc0\uacbd \ubd88\uac00\ub2a5\ud55c \uc21c\uc11c\uac00 \uc788\ub294 \uc2dc\ud000\uc2a4\uc785\ub2c8\ub2e4. List\ub294 \uc0c8\ub85c\uc6b4 \uac12\uc744 \ucd94\uac00\ud558\uac70\ub098 \uc0ad\uc81c\ud558\ub294 \uac83\uc740 \ubd88\uac00\ub2a5\ud558\uc9c0\ub9cc, \uc0c8\ub85c\uc6b4 List\ub97c \ub9cc\ub4e4\uc5b4\ub0b4\ub294 \uc5f0\uc0b0\uc740 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n``` scala\\n// List \uc0dd\uc131\\nval myList = List(1, 2, 3, 4, 5)\\n\\n// \uac12 \ucd94\uac00\\nval newList = myList :+ 6\\n\\n// \uac12 \uc81c\uac70\\nval anotherList = myList.filter(_ != 3)\\n\\n// \uac12 \uc870\ud68c\\nmyList(2) // 3\\n```\\n\\n## Vector\\n\\nVector\ub294 \ubcc0\uacbd \ubd88\uac00\ub2a5\ud55c \uc2dc\ud000\uc2a4\uc785\ub2c8\ub2e4. List\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc0c8\ub85c\uc6b4 \uac12\uc744 \ucd94\uac00\ud558\uac70\ub098 \uc0ad\uc81c\ud558\ub294 \uac83\uc740 \ubd88\uac00\ub2a5\ud558\uc9c0\ub9cc, \uc0c8\ub85c\uc6b4 Vector\ub97c \ub9cc\ub4e4\uc5b4\ub0b4\ub294 \uc5f0\uc0b0\uc740 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n``` scala\\n// Vector \uc0dd\uc131\\nval myVector = Vector(1, 2, 3, 4, 5)\\n\\n// \uac12 \ucd94\uac00\\nval newVector = myVector :+ 6\\n\\n// \uac12 \uc81c\uac70\\nval anotherVector = myVector.filter(_ != 3)\\n\\n// \uac12 \uc870\ud68c\\nmyVector(2) // 3\\n```\\n\\n## Map\\n\\nMap\uc740 \ud0a4\uc640 \uac12\uc758 \uc30d\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc790\ub8cc\uad6c\uc870\uc785\ub2c8\ub2e4. \ud0a4\ub294 \uc911\ubcf5\ub420 \uc218 \uc5c6\uc73c\uba70, \uac12\uc5d0\ub294 \uc911\ubcf5 \uc81c\ud55c\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n``` scala\\n// Map \uc0dd\uc131\\nval myMap = Map(\\"one\\" -> 1, \\"two\\" -> 2, \\"three\\" -> 3)\\n\\n// \uac12 \ucd94\uac00\\nval newMap = myMap + (\\"four\\" -> 4)\\n\\n// \uac12 \uc81c\uac70\\nval anotherMap = myMap - \\"two\\"\\n\\n// \uac12 \uc870\ud68c\\nmyMap(\\"one\\") // 1\\n```\\n\\n## Set\\n\\nSet\uc740 \uc911\ubcf5\ub418\uc9c0 \uc54a\uc740 \uac12\ub4e4\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. \uc21c\uc11c\uac00 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\uc73c\uba70, \ubcc0\uacbd \ubd88\uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n``` scala\\n// Set \uc0dd\uc131\\nval mySet = Set(1, 2, 3, 4, 5)\\n\\n// \uac12 \ucd94\uac00\\nval newSet = mySet + 6\\n\\n// \uac12 \uc81c\uac70\\nval anotherSet = mySet - 3\\n\\n// \uac12 \uc870\ud68c\\nmySet.contains(2) // true\\n\\n```\\n\\n---\\n\\nexport const linkList = [\\n{href: \\"https://docs.scala-lang.org/overviews/scala-book/collections-101.html\\"},\\n]\\n\\nimport ReferenceLink from \\"@site/src/components/ReferenceLink\\";\\n\\n<details>\\n    <summary>Reference</summary>\\n    <ReferenceLink linkList={linkList} />\\n</details>"},{"id":"2023-03-05-mqtt-base","metadata":{"permalink":"/blog/2023-03-05-mqtt-base","source":"@site/blog/2023/03/05/mqtt-base.md","title":"MQTT \ud504\ub85c\ud1a0\ucf5c","description":"MQTT\ub294 Message Queuing Telemetry Transport\uc758 \uc57d\uc790\ub85c, IoT \uae30\uae30\ub4e4 \uac04\uc758 \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc744 \uc704\ud55c \ud504\ub85c\ud1a0\ucf5c\uc785\ub2c8\ub2e4.","date":"2023-03-05T00:00:00.000Z","tags":[{"inline":true,"label":"mqtt","permalink":"/blog/tags/mqtt"},{"inline":true,"label":"server","permalink":"/blog/tags/server"},{"inline":true,"label":"protocol","permalink":"/blog/tags/protocol"}],"readingTime":12.44,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2023-03-05-mqtt-base","title":"MQTT \ud504\ub85c\ud1a0\ucf5c","authors":["eleutherius"],"tags":["mqtt","server","protocol"]},"unlisted":false,"prevItem":{"title":"Collections in scala (2.x)","permalink":"/blog/2023-07-22-scala-collections"},"nextItem":{"title":"\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uae30\ucd08","permalink":"/blog/2023-03-04-typescript-base"}},"content":"MQTT\ub294 Message Queuing Telemetry Transport\uc758 \uc57d\uc790\ub85c, IoT \uae30\uae30\ub4e4 \uac04\uc758 \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc744 \uc704\ud55c \ud504\ub85c\ud1a0\ucf5c\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## MQTT\uc758 \uae30\ubcf8 \uc791\ub3d9 \ubc29\uc2dd\\n\\nMQTT\ub294 \ubc1c\ud589/\uad6c\ub3c5(Publish/Subscribe) \ubaa8\ub378\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774 \ubaa8\ub378\uc5d0\uc11c MQTT \ube0c\ub85c\ucee4\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc774 \uba54\uc2dc\uc9c0\ub97c \ubc1c\ud589\ud558\uace0, \ud574\ub2f9 \uba54\uc2dc\uc9c0\ub97c \uc218\uc2e0\ud560 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc5d0\uac8c \uc804\ub2ec\ud558\ub294 \uc911\uac04 \ub9e4\uac1c\uccb4 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\\n\\nMQTT \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc740 \ube0c\ub85c\ucee4\uc5d0\uac8c \uad6c\ub3c5(subscribe) \uc694\uccad\uc744 \ubcf4\ub0b4\uace0, \ube0c\ub85c\ucee4\ub294 \uad6c\ub3c5\ud55c \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc5d0\uac8c \uba54\uc2dc\uc9c0\ub97c \uc804\ub2ec\ud569\ub2c8\ub2e4. \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc740 \ubc1c\ud589(publish) \uc694\uccad\uc744 \ubcf4\ub0b4\uace0, \ube0c\ub85c\ucee4\ub294 \ud574\ub2f9 \uba54\uc2dc\uc9c0\ub97c \uad6c\ub3c5\ud55c \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc5d0\uac8c \uc804\ub2ec\ud569\ub2c8\ub2e4.\\n\\n## MQTT\uc758 \ud2b9\uc9d5\\n\\n- \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c: MQTT\ub294 TCP/IP \ud504\ub85c\ud1a0\ucf5c \uc704\uc5d0\uc11c \uc791\ub3d9\ud558\uba70, \ub124\ud2b8\uc6cc\ud06c \ub300\uc5ed\ud3ed\uc744 \ucd5c\uc18c\ud654\ud558\uae30 \uc704\ud574 \ucd5c\uc801\ud654\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n- QoS(Quality of Service) \uc9c0\uc6d0: MQTT\ub294 3\uac00\uc9c0 QoS \ub808\ubca8\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4. \uc774\ub97c \uc774\uc6a9\ud574 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4 \uac04\uc758 \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub3c4\ub97c \uc870\uc808\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc720\uc5f0\ud55c \ud1a0\ud53d(Topic) \uad6c\uc870: MQTT\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc774 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0 \ubc1b\uc744 \ub54c, \uc8fc\uc81c(Topic)\ub97c \uc774\uc6a9\ud574 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud569\ub2c8\ub2e4. \uc774\ub97c \uc774\uc6a9\ud574 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4 \uac04\uc758 \ub370\uc774\ud130\ub97c \ubd84\ub958\ud558\uace0 \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc548\uc815\uc131: MQTT\ub294 \uc7a5\uc560 \ubc1c\uc0dd \uc2dc \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc744 \ubcf4\uc7a5\ud558\uae30 \uc704\ud574 \ub2e4\uc591\ud55c \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ube0c\ub85c\ucee4 \uac04\uc758 \ub370\uc774\ud130 \ub3d9\uae30\ud654\ub97c \ud1b5\ud574 \uc7a5\uc560 \ubc1c\uc0dd \uc2dc \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc744 \ubcf4\uc7a5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## MQTT\uc758 \ud65c\uc6a9\\n\\nMQTT\ub294 IoT \ubd84\uc57c\uc5d0\uc11c \ub2e4\uc591\ud558\uac8c \ud65c\uc6a9\ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc2a4\ub9c8\ud2b8 \ud648, \uc2a4\ub9c8\ud2b8 \uc2dc\ud2f0, \uc790\ub3d9\ucc28, \uc0b0\uc5c5 \uc790\ub3d9\ud654 \ub4f1\uc5d0\uc11c \uc0ac\uc6a9\ub429\ub2c8\ub2e4. MQTT\ub294 \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c\uc774\uae30 \ub54c\ubb38\uc5d0, \uc81c\ud55c\ub41c \ub300\uc5ed\ud3ed\uacfc \uc5f0\uacb0\uc131\uc774 \ub0ae\uc740 \ud658\uacbd\uc5d0\uc11c\ub3c4 \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n# MQTT \ud504\ub85c\ud1a0\ucf5c\uc758 \uad6c\uc131\uc694\uc18c\\n\\nMQTT \ud504\ub85c\ud1a0\ucf5c\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uad6c\uc131\uc694\uc18c\ub97c \ud3ec\ud568\ud569\ub2c8\ub2e4.\\n\\n## 1. Broker\\n\\nMQTT \ube0c\ub85c\ucee4\ub294 \uba54\uc2dc\uc9c0\ub97c \ubc1c\ud589\ud558\uace0, \ud574\ub2f9 \uba54\uc2dc\uc9c0\ub97c \uad6c\ub3c5\ud55c \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc5d0\uac8c \uc804\ub2ec\ud558\ub294 \uc911\uac04 \ub9e4\uac1c\uccb4 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \ube0c\ub85c\ucee4\ub294 MQTT \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4 \uac04\uc758 \ud1b5\uc2e0\uc744 \uc870\uc728\ud569\ub2c8\ub2e4.\\n\\n## 2. Publisher\\n\\nMQTT \ubc1c\ud589\uc790\ub294 \uba54\uc2dc\uc9c0\ub97c \ubc1c\ud589\ud558\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\uc785\ub2c8\ub2e4. \ubc1c\ud589\uc790\ub294 \ud2b9\uc815 \uc8fc\uc81c(topic)\uc5d0 \ub300\ud55c \uba54\uc2dc\uc9c0\ub97c \ube0c\ub85c\ucee4\uc5d0\uac8c \uc804\ub2ec\ud569\ub2c8\ub2e4.\\n\\n## 3. Subscriber\\n\\nMQTT \uad6c\ub3c5\uc790\ub294 \ud2b9\uc815 \uc8fc\uc81c(topic)\uc5d0 \ub300\ud55c \uba54\uc2dc\uc9c0\ub97c \uc218\uc2e0\ud558\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\uc785\ub2c8\ub2e4. \uad6c\ub3c5\uc790\ub294 \ube0c\ub85c\ucee4\uc5d0\uac8c \ud2b9\uc815 \uc8fc\uc81c\uc5d0 \ub300\ud55c \uad6c\ub3c5 \uc694\uccad\uc744 \ubcf4\ub0b4\uace0, \ud574\ub2f9 \uc8fc\uc81c\uc5d0 \ub300\ud55c \uba54\uc2dc\uc9c0\ub97c \uc218\uc2e0\ud569\ub2c8\ub2e4.\\n\\n## 4. Topic\\n\\nMQTT\uc5d0\uc11c\ub294 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c, \uc8fc\uc81c(topic)\ub77c\ub294 \uac1c\ub150\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc8fc\uc81c\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc774 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c, \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ub429\ub2c8\ub2e4. \uc8fc\uc81c\ub294 \uc2ac\ub798\uc2dc(/)\ub85c \ubd84\ub9ac\ub41c \ubb38\uc790\uc5f4\ub85c \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n# MQTT \ud504\ub85c\ud1a0\ucf5c\uc758 QoS(Quality of Service)\\n\\nMQTT\ub294 QoS(Quality of Service)\ub77c\ub294 \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. QoS\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\ub4e4\uc774 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c, \ud574\ub2f9 \uba54\uc2dc\uc9c0\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub3c4\ub97c \uc870\uc808\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ub429\ub2c8\ub2e4. MQTT\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 3\uac00\uc9c0 QoS \ub808\ubca8\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n## 1. QoS 0\\n\\nQoS 0\uc740 \ucd5c\ub300 1\ud68c\ub9cc \uc804\uc1a1\ub418\uba70, \uba54\uc2dc\uc9c0\uc758 \uc804\uc1a1 \uc5ec\ubd80\uc5d0 \ub300\ud55c \ud655\uc778 \uc808\ucc28\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774\ub294 \ub300\uc5ed\ud3ed\uc774 \ub0ae\uc740 \ud658\uacbd\uc5d0\uc11c \uc0ac\uc6a9\ud558\uae30 \uc801\ud569\ud569\ub2c8\ub2e4.\\n\\n## 2. QoS 1\\n\\nQoS 1\uc740 \ucd5c\uc18c 1\ud68c \uc774\uc0c1 \uc804\uc1a1\ub418\uba70, \uba54\uc2dc\uc9c0 \uc804\uc1a1 \uc5ec\ubd80\ub97c \ube0c\ub85c\ucee4\uc5d0\uac8c \ud655\uc778\ubc1b\uc2b5\ub2c8\ub2e4. \uc774\ub294 \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc758 \uc2e0\ub8b0\uc131\uc744 \ubcf4\uc7a5\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## 3. QoS 2\\n\\nQoS 2\ub294 \ucd5c\uc18c 2\ud68c \uc774\uc0c1 \uc804\uc1a1\ub418\uba70, \uba54\uc2dc\uc9c0 \uc804\uc1a1 \uc5ec\ubd80\ub97c \ube0c\ub85c\ucee4\uc640 \ud074\ub77c\uc774\uc5b8\ud2b8 \ubaa8\ub450 \ud655\uc778\ubc1b\uc2b5\ub2c8\ub2e4. \uc774\ub294 \ub192\uc740 \uc2e0\ub8b0\uc131\uc774 \uc694\uad6c\ub418\ub294 \ud658\uacbd\uc5d0\uc11c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## MQTT\uc758 \ubcf4\uc548\\n\\nMQTT\ub294 \uae30\ubcf8\uc801\uc73c\ub85c \ubcf4\uc548 \uae30\ub2a5\uc774 \ud0d1\uc7ac\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c, MQTT\ub97c \uc0ac\uc6a9\ud560 \ub54c\uc5d0\ub294 \ubcf4\uc548\uc744 \uc704\ud55c \ucd94\uac00\uc801\uc778 \uc870\uce58\uac00 \ud544\uc694\ud569\ub2c8\ub2e4. \uc774\ub97c \uc704\ud574, SSL/TLS\ub97c \uc774\uc6a9\ud55c \uc554\ud638\ud654, \uc0ac\uc6a9\uc790 \uc778\uc99d \ubc0f \uc811\uadfc \uc81c\uc5b4 \ub4f1\uc758 \ubc29\ubc95\uc774 \uc0ac\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## MQTT\uc640 HTTP \ube44\uad50\\n\\nMQTT\uc640 HTTP\ub294 \ubaa8\ub450 \uc778\ud130\ub137 \ud504\ub85c\ud1a0\ucf5c\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc, \ub450 \ud504\ub85c\ud1a0\ucf5c\uc758 \uc0ac\uc6a9 \ubaa9\uc801\uacfc \ud2b9\uc9d5\uc740 \ub2e4\ub985\ub2c8\ub2e4.\\n\\n### MQTT\uc758 \uc0ac\uc6a9 \ubaa9\uc801\\n\\nMQTT\ub294 IoT \uae30\uae30\ub4e4 \uac04\uc758 \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc744 \uc704\ud55c \ud504\ub85c\ud1a0\ucf5c\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c, \uc81c\ud55c\ub41c \ub300\uc5ed\ud3ed\uacfc \uc5f0\uacb0\uc131\uc774 \ub0ae\uc740 \ud658\uacbd\uc5d0\uc11c\ub3c4 \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud558\uba70, \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c\ub85c \ucd5c\uc801\ud654\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### HTTP\uc758 \uc0ac\uc6a9 \ubaa9\uc801\\n\\nHTTP\ub294 \uc6f9\uc0c1\uc5d0\uc11c \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\uae30 \uc704\ud55c \ud504\ub85c\ud1a0\ucf5c\uc785\ub2c8\ub2e4. \uc8fc\ub85c \uc6f9 \ube0c\ub77c\uc6b0\uc800\uc640 \uc6f9 \uc11c\ubc84 \uac04\uc758 \ud1b5\uc2e0\uc744 \uc704\ud574 \uc0ac\uc6a9\ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c, \ub300\uc5ed\ud3ed\uacfc \uc5f0\uacb0\uc131\uc774 \ub192\uc740 \ud658\uacbd\uc5d0\uc11c \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud558\uba70, \ud14d\uc2a4\ud2b8 \uae30\ubc18\uc758 \ud504\ub85c\ud1a0\ucf5c\ub85c \ucd5c\uc801\ud654\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### MQTT\uc640 HTTP\uc758 \ud2b9\uc9d5 \ube44\uad50\\n\\nMQTT\uc640 HTTP\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \ud2b9\uc9d5\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n| \ud2b9\uc9d5 | MQTT | HTTP |\\n| --- | --- | --- |\\n| \ud504\ub85c\ud1a0\ucf5c \uc720\ud615 | \uba54\uc2dc\uc9c0 \uae30\ubc18 | \uc694\uccad/\uc751\ub2f5 \uae30\ubc18 |\\n| \uc5f0\uacb0 \ubc29\uc2dd | \uc138\uc158 \uae30\ubc18 | \uc5f0\uacb0 \uae30\ubc18 |\\n| \ud1b5\uc2e0 \ubc29\uc2dd | \ubc1c\ud589/\uad6c\ub3c5 | \uc694\uccad/\uc751\ub2f5 |\\n| \ub300\uc5ed\ud3ed \uc694\uad6c | \ub0ae\uc74c | \ub192\uc74c |\\n| \uc5f0\uacb0\uc131 \uc694\uad6c | \ub0ae\uc74c | \ub192\uc74c |\\n| \uc0ac\uc6a9 \ubaa9\uc801 | IoT \uae30\uae30 \uac04\uc758 \uba54\uc2dc\uc9c0 \uc804\uc1a1 | \uc6f9\uc0c1\uc5d0\uc11c \ub370\uc774\ud130 \uc8fc\uace0\ubc1b\uae30 |\\n| \ucd5c\uc801\ud654 | \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c | \ud14d\uc2a4\ud2b8 \uae30\ubc18 \ud504\ub85c\ud1a0\ucf5c |\\n\\n## MQTT\uc758 \uc7a5\ub2e8\uc810\\n\\n### \uc7a5\uc810\\n\\n- \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c\uc774\uae30 \ub54c\ubb38\uc5d0, \uc81c\ud55c\ub41c \ub300\uc5ed\ud3ed\uacfc \uc5f0\uacb0\uc131\uc774 \ub0ae\uc740 \ud658\uacbd\uc5d0\uc11c\ub3c4 \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n- \ubc1c\ud589/\uad6c\ub3c5 \ubaa8\ub378\uc744 \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc5d0, \ud074\ub77c\uc774\uc5b8\ud2b8 \uac04\uc758 \ud1b5\uc2e0\uc774 \ud6a8\uc728\uc801\uc785\ub2c8\ub2e4.\\n- QoS \ub808\ubca8\uc744 \uc9c0\uc6d0\ud558\uae30 \ub54c\ubb38\uc5d0, \uba54\uc2dc\uc9c0 \uc804\uc1a1\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub3c4\ub97c \uc870\uc808\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc720\uc5f0\ud55c \ud1a0\ud53d(Topic) \uad6c\uc870\ub97c \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc5d0, \ub370\uc774\ud130\ub97c \uc27d\uac8c \ubd84\ub958\ud558\uace0 \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ub2e4\uc591\ud55c \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\uae30 \ub54c\ubb38\uc5d0, \uc548\uc815\uc131\uc744 \ubcf4\uc7a5\ud569\ub2c8\ub2e4.\\n\\n### \ub2e8\uc810\\n\\n- \uae30\ubcf8\uc801\uc73c\ub85c \ubcf4\uc548 \uae30\ub2a5\uc774 \ud0d1\uc7ac\ub418\uc5b4 \uc788\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0, \ubcf4\uc548\uc744 \uc704\ud55c \ucd94\uac00\uc801\uc778 \uc870\uce58\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- HTTP\uc640 \uac19\uc740 \uc694\uccad/\uc751\ub2f5 \uae30\ubc18\uc758 \ud504\ub85c\ud1a0\ucf5c\ubcf4\ub2e4\ub294 \uad6c\ud604\uc774 \ubcf5\uc7a1\ud569\ub2c8\ub2e4.\\n- QoS \ub808\ubca8\uc774 \ub192\uc544\uc9c8\uc218\ub85d \ub300\uc5ed\ud3ed\uacfc \uc131\ub2a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce69\ub2c8\ub2e4.\\n\\n## MQTT\uc758 \ud65c\uc6a9 \uc608\uc2dc\\n\\n### \uc2a4\ub9c8\ud2b8 \ud648\\n\\nMQTT\ub294 \uc2a4\ub9c8\ud2b8 \ud648 \ubd84\uc57c\uc5d0\uc11c \ub2e4\uc591\ud558\uac8c \ud65c\uc6a9\ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc628\ub3c4, \uc2b5\ub3c4, \uc870\ub3c4 \ub4f1\uc758 \uc13c\uc11c \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud558\uace0, \ud574\ub2f9 \ub370\uc774\ud130\ub97c \uc774\uc6a9\ud574 \uc790\ub3d9\ud654 \uae30\ub2a5\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2a4\ub9c8\ud2b8 \uc2dc\ud2f0\\n\\nMQTT\ub294 \uc2a4\ub9c8\ud2b8 \uc2dc\ud2f0 \ubd84\uc57c\uc5d0\uc11c\ub3c4 \ud65c\uc6a9\ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uacf5\uae30\uc9c8, \uc2e4\uc2dc\uac04 \uad50\ud1b5 \uc815\ubcf4, CCTV \ub4f1\uc758 \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud558\uace0, \ud574\ub2f9 \ub370\uc774\ud130\ub97c \uc774\uc6a9\ud574 \ub3c4\uc2dc\uc758 \uc548\uc804\uacfc \ud3b8\uc758\ub97c \uc81c\uacf5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc790\ub3d9\ucc28\\n\\nMQTT\ub294 \uc790\ub3d9\ucc28 \ubd84\uc57c\uc5d0\uc11c\ub3c4 \ud65c\uc6a9\ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ucc28\ub7c9\uc758 \uc13c\uc11c \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud558\uace0, \ud574\ub2f9 \ub370\uc774\ud130\ub97c \uc774\uc6a9\ud574 \uc6b4\uc804\uc790\uc5d0\uac8c \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\uac70\ub098, \uc790\uc728\uc8fc\ud589 \uae30\ub2a5 \ub4f1\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc0b0\uc5c5 \uc790\ub3d9\ud654\\n\\nMQTT\ub294 \uc0b0\uc5c5 \uc790\ub3d9\ud654 \ubd84\uc57c\uc5d0\uc11c\ub3c4 \ud65c\uc6a9\ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uacf5\uc7a5 \ub0b4\uc758 \uc13c\uc11c \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud558\uace0, \ud574\ub2f9 \ub370\uc774\ud130\ub97c \uc774\uc6a9\ud574 \uc0dd\uc0b0 \ub77c\uc778\uc744 \uc81c\uc5b4\ud558\uac70\ub098, \uace0\uc7a5 \uc9d5\ud6c4\ub97c \uc608\uce21\ud558\ub294 \ub4f1\uc758 \uae30\ub2a5\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## MQTT \ube0c\ub85c\ucee4\\n\\nMQTT \ube0c\ub85c\ucee4\ub294 \uba54\uc2dc\uc9c0\ub97c \uc218\uc2e0\ud558\uace0 \ubc1c\uc2e0\ud558\ub294 \uc911\uac04 \ub2e8\uacc4\ub85c \uc0ac\uc6a9\ub429\ub2c8\ub2e4. \ubaa8\ub4e0 MQTT \ud074\ub77c\uc774\uc5b8\ud2b8\ub294 \ube0c\ub85c\ucee4\uc5d0 \uc5f0\uacb0\ud558\uc5ec \uba54\uc2dc\uc9c0\ub97c \ubc1c\ud589\ud558\uace0 \uc218\uc2e0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### Mosquitto\\n\\nMosquitto\ub294 Eclipse Foundation\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \uc624\ud508\uc18c\uc2a4 MQTT \ube0c\ub85c\ucee4\uc785\ub2c8\ub2e4. Mosquitto\ub294 C\ub85c \uc791\uc131\ub418\uc5b4 \uc788\uc73c\uba70, \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c\uc744 \uc9c0\uc6d0\ud558\uae30 \ub54c\ubb38\uc5d0, IoT \ubd84\uc57c\uc5d0\uc11c \ub9ce\uc774 \uc0ac\uc6a9\ub429\ub2c8\ub2e4. Mosquitto\ub294 \ub2e4\uc591\ud55c \uc6b4\uc601\uccb4\uc81c\uc5d0\uc11c \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud558\uba70, \ud2b9\ud788 Raspberry Pi\uc640 \uac19\uc740 \ubcf4\ub4dc \ucef4\ud4e8\ud130\uc5d0\uc11c \uc0ac\uc6a9\uc774 \uc6a9\uc774\ud569\ub2c8\ub2e4.\\n\\n### EMQ X\\n\\nEMQ X\ub294 \uc624\ud508\uc18c\uc2a4 MQTT \ube0c\ub85c\ucee4\ub85c, \ub2e4\uc591\ud55c \ud504\ub85c\ud1a0\ucf5c \uc9c0\uc6d0\uacfc \ud655\uc7a5\uc131\uc774 \uc6b0\uc218\ud569\ub2c8\ub2e4. EMQ X\ub294 Erlang \uc5b8\uc5b4\ub85c \uc791\uc131\ub418\uc5b4 \uc788\uc73c\uba70, \uc218\ubc31\ub9cc \uac1c\uc758 \ub3d9\uc2dc \uc811\uc18d\uc744 \uc9c0\uc6d0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. EMQ X\ub294 \uae30\uc5c5\uc6a9\uc73c\ub85c \uac1c\ubc1c\ub418\uc5c8\uc73c\uba70, IoT \ubd84\uc57c\uc5d0\uc11c \ub9ce\uc774 \uc0ac\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## \uacb0\ub860\\n\\nMQTT\ub294 IoT \ubd84\uc57c\uc5d0\uc11c \ub9ce\uc774 \uc0ac\uc6a9\ub418\ub294 \uacbd\ub7c9 \ud504\ub85c\ud1a0\ucf5c \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. MQTT\ub294 \uc81c\ud55c\ub41c \ub300\uc5ed\ud3ed\uacfc \uc5f0\uacb0\uc131\uc774 \ub0ae\uc740 \ud658\uacbd\uc5d0\uc11c\ub3c4 \uc0ac\uc6a9\uc774 \uac00\ub2a5\ud558\uba70, \ubc1c\ud589/\uad6c\ub3c5 \ubaa8\ub378\uc744 \uc0ac\uc6a9\ud558\uc5ec \ud074\ub77c\uc774\uc5b8\ud2b8 \uac04\uc758 \ud1b5\uc2e0\uc774 \ud6a8\uc728\uc801\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc, \uae30\ubcf8\uc801\uc73c\ub85c \ubcf4\uc548 \uae30\ub2a5\uc774 \ud0d1\uc7ac\ub418\uc5b4 \uc788\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0, \ubcf4\uc548\uc744 \uc704\ud55c \ucd94\uac00\uc801\uc778 \uc870\uce58\uac00 \ud544\uc694\ud569\ub2c8\ub2e4. MQTT \ube0c\ub85c\ucee4\ub85c\ub294 Mosquitto\uc640 EMQ X \ub4f1\uc774 \uc788\uc73c\uba70, \uac01\uac01\uc758 \ud2b9\uc9d5\uc5d0 \ub530\ub77c \uc0ac\uc6a9\uc774 \uacb0\uc815\ub429\ub2c8\ub2e4."},{"id":"2023-03-04-typescript-base","metadata":{"permalink":"/blog/2023-03-04-typescript-base","source":"@site/blog/2023/03/04/typescript-base.md","title":"\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uae30\ucd08","description":"\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\ub294 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \uc0c1\uc704 \uc9d1\ud569 \uc5b8\uc5b4\ub85c, \uc815\uc801 \ud0c0\uc785\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4. \uc774\ub294 \uac1c\ubc1c\uc790\uac00 \ucf54\ub4dc\ub97c \uc791\uc131\ud560 \ub54c \ubcc0\uc218\uc758 \ub370\uc774\ud130 \ud0c0\uc785\uc744 \uba85\uc2dc\ud574\uc8fc\uc5b4 \ucf54\ub4dc\uc758 \uc548\uc815\uc131\uacfc \uac00\ub3c5\uc131\uc744 \ub192\uc774\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.","date":"2023-03-04T00:00:00.000Z","tags":[{"inline":false,"label":"javascript","permalink":"/blog/tags/javascript","description":"javascript"},{"inline":false,"label":"typescript","permalink":"/blog/tags/typescript","description":"typescript"},{"inline":false,"label":"web","permalink":"/blog/tags/web","description":"web"}],"readingTime":6.54,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2023-03-04-typescript-base","title":"\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uae30\ucd08","authors":["eleutherius"],"tags":["javascript","typescript","web"]},"unlisted":false,"prevItem":{"title":"MQTT \ud504\ub85c\ud1a0\ucf5c","permalink":"/blog/2023-03-05-mqtt-base"},"nextItem":{"title":"\uc720\uc6a9\ud55c HTML \ud0dc\uadf8","permalink":"/blog/2021-09-05-useful-HTML-tags"}},"content":"\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\ub294 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \uc0c1\uc704 \uc9d1\ud569 \uc5b8\uc5b4\ub85c, \uc815\uc801 \ud0c0\uc785\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4. \uc774\ub294 \uac1c\ubc1c\uc790\uac00 \ucf54\ub4dc\ub97c \uc791\uc131\ud560 \ub54c \ubcc0\uc218\uc758 \ub370\uc774\ud130 \ud0c0\uc785\uc744 \uba85\uc2dc\ud574\uc8fc\uc5b4 \ucf54\ub4dc\uc758 \uc548\uc815\uc131\uacfc \uac00\ub3c5\uc131\uc744 \ub192\uc774\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ubcc0\uc218 \uc120\uc5b8\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \ubcc0\uc218\ub97c \uc120\uc5b8\ud560 \ub54c\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n```ts\\nlet \ubcc0\uc218\uc774\ub984: \ub370\uc774\ud130\ud0c0\uc785 = \uac12;\\n\\n```\\n\\n\uc608\ub97c \ub4e4\uc5b4, \ubb38\uc790\uc5f4\uc744 \uc800\uc7a5\ud558\ub294 \ubcc0\uc218\ub97c \uc120\uc5b8\ud558\uace0 \uac12\uc744 \ud560\ub2f9\ud558\ub824\uba74 \ub2e4\uc74c\uacfc \uac19\uc774 \uc791\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```ts\\nlet myString: string = \\"\uc548\ub155\ud558\uc138\uc694!\\";\\n\\n```\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c\ub294 \ubcc0\uc218\uc5d0 \uc800\uc7a5\ub418\ub294 \uac12\uc774 \ub370\uc774\ud130 \ud0c0\uc785\uacfc \uc77c\uce58\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0 \ucef4\ud30c\uc77c \uc5d0\ub7ec\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 \uac1c\ubc1c\uc790\uac00 \ubbf8\ub9ac \ud0c0\uc785 \uc5d0\ub7ec\ub97c \ubc29\uc9c0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ud568\uc218 \uc120\uc5b8\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \ud568\uc218\ub97c \uc120\uc5b8\ud560 \ub54c\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n```ts\\nfunction \ud568\uc218\uc774\ub984(\ub9e4\uac1c\ubcc0\uc218: \ub370\uc774\ud130\ud0c0\uc785): \ubc18\ud658\ud0c0\uc785 {\\n  // \ud568\uc218 \ub0b4\uc6a9\\n}\\n\\n```\\n\\n\uc608\ub97c \ub4e4\uc5b4, \uc22b\uc790\ub97c \ub450 \uac1c \ubc1b\uc544\uc11c \ub354\ud55c \uacb0\uacfc\ub97c \ubc18\ud658\ud558\ub294 \ud568\uc218\ub97c \uc791\uc131\ud558\ub824\uba74 \ub2e4\uc74c\uacfc \uac19\uc774 \uc791\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```ts\\nfunction addNumbers(num1: number, num2: number): number {\\n  return num1 + num2;\\n}\\n\\n```\\n\\n\ub9c8\ucc2c\uac00\uc9c0\ub85c, \ud568\uc218\uc758 \ub9e4\uac1c\ubcc0\uc218\uc640 \ubc18\ud658\uac12\uc758 \ub370\uc774\ud130 \ud0c0\uc785\uc774 \uc77c\uce58\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0 \ucef4\ud30c\uc77c \uc5d0\ub7ec\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.\\n\\n## \uc778\ud130\ud398\uc774\uc2a4\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \uc778\ud130\ud398\uc774\uc2a4\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc791\uc131\ud569\ub2c8\ub2e4.\\n\\n```ts\\ninterface \uc778\ud130\ud398\uc774\uc2a4\uc774\ub984 {\\n  \uc18d\uc131\uc774\ub984: \ub370\uc774\ud130\ud0c0\uc785;\\n}\\n\\n```\\n\\n\uc608\ub97c \ub4e4\uc5b4, \ub2e4\uc74c\uacfc \uac19\uc740 \uad6c\uc870\ub97c \uac00\uc9c4 \ub370\uc774\ud130\ub97c \ub2e4\ub8e8\ub294 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uc791\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```ts\\ninterface Person {\\n  name: string;\\n  age: number;\\n  email: string;\\n}\\n\\n```\\n\\n\uc778\ud130\ud398\uc774\uc2a4\ub294 \uac1d\uccb4\uc758 \uad6c\uc870\ub97c \uc815\uc758\ud569\ub2c8\ub2e4. \uc704\uc758 \uc608\uc2dc\uc5d0\uc11c\ub294 \uc774\ub984, \ub098\uc774, \uc774\uba54\uc77c \uc8fc\uc18c\ub97c \uac00\uc9c4 \uac1d\uccb4\uac00 Person \uc778\ud130\ud398\uc774\uc2a4\uc758 \uaddc\uaca9\uc5d0 \ub9de\uc544\uc57c \ud55c\ub2e4\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.\\n\\n## \ud074\ub798\uc2a4\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \ud074\ub798\uc2a4\ub97c \uc791\uc131\ud560 \ub54c\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n```ts\\nclass \ud074\ub798\uc2a4\uc774\ub984 {\\n  \uc18d\uc131\uc774\ub984: \ub370\uc774\ud130\ud0c0\uc785;\\n\\n  constructor(\ub9e4\uac1c\ubcc0\uc218: \ub370\uc774\ud130\ud0c0\uc785) {\\n    // \uc0dd\uc131\uc790 \ub0b4\uc6a9\\n  }\\n\\n  \uba54\uc11c\ub4dc\uc774\ub984() {\\n    // \uba54\uc11c\ub4dc \ub0b4\uc6a9\\n  }\\n}\\n\\n```\\n\\n\uc608\ub97c \ub4e4\uc5b4, \ub2e4\uc74c\uacfc \uac19\uc740 \uc18d\uc131\uacfc \uba54\uc11c\ub4dc\ub97c \uac00\uc9c4 \ud074\ub798\uc2a4\ub97c \uc791\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```ts\\nclass Car {\\n  brand: string;\\n  speed: number;\\n\\n  constructor(brand: string) {\\n    this.brand = brand;\\n    this.speed = 0;\\n  }\\n\\n  accelerate() {\\n    this.speed += 10;\\n  }\\n}\\n\\n```\\n\\n\uc704\uc758 \uc608\uc2dc\uc5d0\uc11c Car \ud074\ub798\uc2a4\ub294 brand\uc640 speed\ub77c\ub294 \uc18d\uc131\uc744 \uac00\uc9c0\uace0 \uc788\uc73c\uba70, accelerate\ub77c\ub294 \uba54\uc11c\ub4dc\ub97c \uc2e4\ud589\ud558\uba74 speed \uc18d\uc131\uc758 \uac12\uc744 10 \uc99d\uac00\uc2dc\ud0b5\ub2c8\ub2e4.\\n\\n## \ub370\ucf54\ub808\uc774\ud130\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \ub370\ucf54\ub808\uc774\ud130\ub294 \ud074\ub798\uc2a4, \uba54\uc11c\ub4dc, \uc18d\uc131 \ub4f1\uc5d0 \ucd94\uac00\uc801\uc778 \uae30\ub2a5\uc744 \ubd80\uc5ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub370\ucf54\ub808\uc774\ud130\ub97c \uc0ac\uc6a9\ud558\uba74 \ucf54\ub4dc\uc758 \uac00\ub3c5\uc131\uc744 \ub192\uc774\uace0 \uc911\ubcf5\ub41c \ub85c\uc9c1\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c\uc740 \ub370\ucf54\ub808\uc774\ud130\ub97c \uc0ac\uc6a9\ud558\uc5ec \ud074\ub798\uc2a4\uc5d0 \ub85c\uadf8\ub97c \ucd94\uac00\ud558\ub294 \uc608\uc2dc\uc785\ub2c8\ub2e4.\\n\\n```ts\\nfunction log(target: any) {\\n  console.log(target);\\n}\\n\\n@log\\nclass MyClass {\\n  // \ud074\ub798\uc2a4 \ub0b4\uc6a9\\n}\\n\\n```\\n\\n\uc704\uc758 \uc608\uc2dc\uc5d0\uc11c log \ud568\uc218\ub294 MyClass \ud074\ub798\uc2a4\ub97c \uc778\uc790\ub85c \ubc1b\uc544 \ub85c\uadf8\ub97c \ucd9c\ub825\ud569\ub2c8\ub2e4. @log \ub370\ucf54\ub808\uc774\ud130\ub294 MyClass \ud074\ub798\uc2a4\uc5d0 \ub85c\uadf8\ub97c \ucd94\uac00\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\\n\\n## \uc81c\ub124\ub9ad\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \uc81c\ub124\ub9ad\uc740 \ub2e4\uc591\ud55c \ud0c0\uc785\uc758 \ub370\uc774\ud130\ub97c \ub2e4\ub8f0 \uc218 \uc788\ub3c4\ub85d \ud0c0\uc785\uc744 \ub9e4\uac1c\ubcc0\uc218\ud654\ud558\ub294 \uae30\ub2a5\uc785\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 \uc911\ubcf5 \ucf54\ub4dc\ub97c \uc904\uc774\uace0 \uc7ac\uc0ac\uc6a9\uc131\uc744 \ub192\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c\uc740 \uc81c\ub124\ub9ad\uc744 \uc0ac\uc6a9\ud558\uc5ec \ubc30\uc5f4\uc758 \uc694\uc18c\ub97c \ucd9c\ub825\ud558\ub294 \ud568\uc218\ub97c \uc791\uc131\ud558\ub294 \uc608\uc2dc\uc785\ub2c8\ub2e4.\\n\\n```ts\\nfunction printArray<T>(arr: T[]) {\\n  for (let i = 0; i < arr.length; i++) {\\n    console.log(arr[i]);\\n  }\\n}\\n\\nlet myArray = [1, 2, 3, 4, 5];\\nprintArray<number>(myArray);\\n\\n```\\n\\n\uc704\uc758 \uc608\uc2dc\uc5d0\uc11c printArray \ud568\uc218\ub294 \uc81c\ub124\ub9ad \ud0c0\uc785 T\ub97c \ub9e4\uac1c\ubcc0\uc218\ub85c \ubc1b\uc544 T \ud0c0\uc785\uc758 \ubc30\uc5f4\uc744 \ucd9c\ub825\ud569\ub2c8\ub2e4. myArray \ubcc0\uc218\ub294 \uc22b\uc790 \ud0c0\uc785\uc758 \ubc30\uc5f4\uc774\ubbc0\ub85c printArray \ud568\uc218\uc5d0 number \ud0c0\uc785\uc744 \uc81c\ub124\ub9ad \ub9e4\uac1c\ubcc0\uc218\ub85c \uc804\ub2ec\ud569\ub2c8\ub2e4.\\n\\n## \uacb0\ub860\\n\\n\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\ub294 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \uc0c1\uc704 \uc9d1\ud569 \uc5b8\uc5b4\ub85c, \uc815\uc801 \ud0c0\uc785\uc744 \uc9c0\uc6d0\ud558\uba70 \uac1c\ubc1c\uc790\uac00 \ucf54\ub4dc\uc758 \uc548\uc815\uc131\uacfc \uac00\ub3c5\uc131\uc744 \ub192\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubcc0\uc218, \ud568\uc218, \uc778\ud130\ud398\uc774\uc2a4, \ud074\ub798\uc2a4 \ub4f1\uc744 \uc791\uc131\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uac04\ub2e8\ud788 \uc18c\uac1c\ud558\uc600\uc73c\uba70, \ub370\ucf54\ub808\uc774\ud130\ub97c \uc0ac\uc6a9\ud558\uc5ec \ucf54\ub4dc\uc758 \uac00\ub3c5\uc131\uacfc \uc720\uc9c0\ubcf4\uc218\uc131\uc744 \ub192\uc774\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc54c\uc544\ubcf4\uc558\uc2b5\ub2c8\ub2e4. \ub610\ud55c, \uc81c\ub124\ub9ad\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc911\ubcf5 \ucf54\ub4dc\ub97c \uc904\uc774\uace0 \uc7ac\uc0ac\uc6a9\uc131\uc744 \ub192\uc774\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc54c\uc544\ubcf4\uc558\uc2b5\ub2c8\ub2e4. \uc774\uc81c \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc548\uc815\uc801\uc774\uace0 \uac00\ub3c5\uc131\uc774 \ub192\uc740 \ucf54\ub4dc\ub97c \uc791\uc131\ud574\ubcf4\uc138\uc694!"},{"id":"2021-09-05-useful-HTML-tags","metadata":{"permalink":"/blog/2021-09-05-useful-HTML-tags","source":"@site/blog/2021/09/05/useful-HTML-tags/index.mdx","title":"\uc720\uc6a9\ud55c HTML \ud0dc\uadf8","description":"img.png","date":"2021-09-05T00:00:00.000Z","tags":[{"inline":true,"label":"html","permalink":"/blog/tags/html"},{"inline":false,"label":"web","permalink":"/blog/tags/web","description":"web"},{"inline":true,"label":"Semantic","permalink":"/blog/tags/semantic"}],"readingTime":0.755,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2021-09-05-useful-HTML-tags","title":"\uc720\uc6a9\ud55c HTML \ud0dc\uadf8","authors":["eleutherius"],"tags":["html","web","Semantic"]},"unlisted":false,"prevItem":{"title":"\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uae30\ucd08","permalink":"/blog/2023-03-04-typescript-base"},"nextItem":{"title":"docker \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 timezone","permalink":"/blog/2021-09-01-docker-timezone"}},"content":"![img.png](./img.png)\\n\\n\x3c!--truncate--\x3e\\n\\n## `<details/>` + `<summary/>`\\n\\n- \ud074\ub9ad \uc2dc, \ub0b4\uc6a9\uc744 \ubcf4\uc5ec\uc8fc\ub294 toggle\uc744 \uc9c0\uc6d0\\n- \ud544\uc790\ub294 `<details/>`\ub97c \uc0ac\uc6a9\ud558\uc5ec \ucc38\uc870 URL\uc744 \uc791\uc131\\n\\n```html\\n<details>\\n    <summary>Click Me!!!</summary>\\n    <div>\\n        <ul>\\n            <li>\ubaa9\ub85d1</li>\\n            <li>\ubaa9\ub85d2</li>\\n            <li>\ubaa9\ub85d3</li>\\n        </ul>\\n    </div>\\n</details>\\n```\\n\\n<details>\\n    <summary>Click Me!!!</summary>\\n    <div>\\n        <ul>\\n            <li>\ubaa9\ub85d1</li>\\n            <li>\ubaa9\ub85d2</li>\\n            <li>\ubaa9\ub85d3</li>\\n        </ul>\\n    </div>\\n</details>\\n\\n## `<kbd/>`\\n\\n- keyboard \uc785\ub825\uc744 \ud45c\ud604\ud560 \ub54c \uc0ac\uc6a9\ub429\ub2c8\ub2e4\\n\\n\\n```html\\n<p>Press <kbd>Ctrl</kbd> + <kbd>C</kbd> to copy text (Windows).</p>\\n<p>Press <kbd>Cmd</kbd> + <kbd>C</kbd> to copy text (Mac OS).</p>\\n```\\n\\n<p>Press <kbd>Ctrl</kbd> + <kbd>C</kbd> to copy text (Windows).</p>\\n<p>Press <kbd>Cmd</kbd> + <kbd>C</kbd> to copy text (Mac OS).</p>\\n\\n---\\n\\nexport const linkList = [\\n    {href: \\"https://youtu.be/9lP8TcVJv-I\\"},\\n    {href: \\"https://www.w3schools.com/tags/default.asp\\"},\\n]\\n\\nimport ReferenceLink from \\"@site/src/components/ReferenceLink\\";\\n\\n<details>\\n    <summary>Reference</summary>\\n    <ReferenceLink linkList={linkList} />\\n</details>"},{"id":"2021-09-01-docker-timezone","metadata":{"permalink":"/blog/2021-09-01-docker-timezone","source":"@site/blog/2021/09/01/docker-timezone/index.mdx","title":"docker \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 timezone","description":"logo","date":"2021-09-01T00:00:00.000Z","tags":[{"inline":true,"label":"dev","permalink":"/blog/tags/dev"},{"inline":true,"label":"infra","permalink":"/blog/tags/infra"},{"inline":true,"label":"docker","permalink":"/blog/tags/docker"},{"inline":true,"label":"docker-compose","permalink":"/blog/tags/docker-compose"}],"readingTime":1.185,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2021-09-01-docker-timezone","title":"docker \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 timezone","authors":["eleutherius"],"tags":["dev","infra","docker","docker-compose"]},"unlisted":false,"prevItem":{"title":"\uc720\uc6a9\ud55c HTML \ud0dc\uadf8","permalink":"/blog/2021-09-05-useful-HTML-tags"},"nextItem":{"title":"package.json \uc5c5\ub370\uc774\ud2b8 \ud655\uc778","permalink":"/blog/2021-08-27-npm-check-updates"}},"content":"![logo](./logo.png)\\n\\n\x3c!--truncate--\x3e\\n\\n## \uac1c\uc694\\n\\ndocker \ud639\uc740 docker-compose\ub85c \uc11c\ube44\uc2a4\ub97c \uc124\uce58 \ubc0f \uc6b4\uc601\ud558\ub2e4\ubcf4\uba74 \uc2dc\uac04\uac12\uc774 9\uc2dc\uac04 \ub290\ub9b0 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ud574\ub2f9 \uacbd\uc6b0\ub294 docker \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80\uc758 TimeZone\uc774 EST \ud639\uc740 UTC\ub85c \uc124\uc815\ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub54c ntp\ub97c \uc124\uce58\ud558\uc5ec \uc11c\ubc84\uc2dc\uac04\uc744 \ub9de\ucd94\ub824\ud574\ub3c4 \uc801\uc6a9\uc774 \ub418\uc9c0 \uc54a\uace0 \uc11c\ubc84 \uc790\uccb4\uc758 timezone\uc744 \ubcc0\uacbd\ud558\uc5ec \uc9c4\ud589\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n## \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 TimeZone \ud655\uc778\\n\\n### docker\\n\\n```bash\\ndocker exec -it `${container_name || ID}` /bin/bash\\ndate\\nls -la /etc/localtime\\n```\\n\\n### docker-compose\\n\\n```bash\\ndocker-compose exec ${NAME} bash\\ndate\\nls -la /etc/localtime\\n```\\n\\n## \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 TimeZone \uc124\uc815\\n\\n> \ucee8\ud14c\uc774\ub108\uc758 \ub0b4\ubd80 TimeZone\uc744 \uc124\uc815\ud558\uae30 \uc704\ud574\uc11c\ub294 TimeZone \uc815\ubcf4\ub97c \ub9c8\uc6b4\ud2b8\ud558\ub294\uac83\uc73c\ub85c \ud574\uacb0 \ud560 \uc218 \uc788\ub2e4.\\n\\n### docker\\n\\n```bash\\ndocker run -it --rm -v /usr/share/zoneinfo/Asia/Seoul:/etc/localtime:ro centos bash\\n```\\n\\n### docker-compose\\n\\n```yaml\\nservices:\\n  centos:\\n    container_name: container\\n    hostname: container\\n    image: centos\\n    volumes:\\n      - /usr/share/zoneinfo/Asia/Seoul:/etc/localtime:ro # read-only\\n```\\n\\nexport const linkList = [\\n    {href: \\"https://forums.docker.com/t/synchronize-timezone-from-host-to-container/39116\\"},\\n]\\n\\nimport ReferenceLink from \\"@site/src/components/ReferenceLink\\";\\n\\n<details>\\n    <summary>Reference</summary>\\n    <ReferenceLink linkList={linkList} />\\n</details>"},{"id":"2021-08-27-npm-check-updates","metadata":{"permalink":"/blog/2021-08-27-npm-check-updates","source":"@site/blog/2021/08/27/npm-check-updates/index.md","title":"package.json \uc5c5\ub370\uc774\ud2b8 \ud655\uc778","description":"logo.png","date":"2021-08-27T00:00:00.000Z","tags":[{"inline":true,"label":"dev","permalink":"/blog/tags/dev"},{"inline":true,"label":"setting","permalink":"/blog/tags/setting"},{"inline":false,"label":"javascript","permalink":"/blog/tags/javascript","description":"javascript"},{"inline":true,"label":"nodejs","permalink":"/blog/tags/nodejs"},{"inline":true,"label":"npm","permalink":"/blog/tags/npm"}],"readingTime":0.59,"hasTruncateMarker":true,"authors":[{"name":"hwayoung kim","title":"\uc18c\uc8fc\uac19\uc740 \uac1c\ubc1c\uc790","url":"https://github.com/EleutheriusKim","page":{"permalink":"/blog/authors/eleutherius"},"imageURL":"https://avatars1.githubusercontent.com/u/50225173?s=460&v=4","key":"eleutherius"}],"frontMatter":{"slug":"2021-08-27-npm-check-updates","title":"package.json \uc5c5\ub370\uc774\ud2b8 \ud655\uc778","authors":["eleutherius"],"tags":["dev","setting","javascript","nodejs","npm"]},"unlisted":false,"prevItem":{"title":"docker \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 timezone","permalink":"/blog/2021-09-01-docker-timezone"}},"content":"![logo.png](./logo.png)\\n\\n\x3c!--truncate--\x3e\\n\\n## \uc18c\uac1c\\n\\nnpm-check-updates\ub77c\ub294 \ubaa8\ub4c8\uc774 \uc788\ub2e4.\\n\\n\ud574\ub2f9 \ubaa8\ub4c8\uc744 \uc0ac\uc6a9\ud558\uba74 package.json \ub0b4\uc5d0 \ub4f1\ub85d\ub41c \ubaa8\ub4c8\ub4e4\uc744 \uc758\uc874\uc131\uc5d0 \ub9de\uac8c \ucd5c\uc2e0\ubc84\uc804\uc73c\ub85c \uc5c5\ub370\uc774\ud2b8\uac00 \uac00\ub2a5\ud558\ub2e4.\\n`npm -g`\ub97c \uc0ac\uc6a9\ud558\uc5ec global\ub85c \uc124\uce58\ud558\uc5ec \uc0ac\uc6a9\ud558\uba74 \ud3b8\ud558\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4.\\n\\n- [https://www.npmjs.com/package/npm-check-updates](https://www.npmjs.com/package/npm-check-updates)\\n\\n## \uc124\uce58\ubc29\ubc95\\n\\n```bash\\nnpm i -g npm-check-updates\\n```\\n\\n![module_install](./module_install.png)\\n\\n## \uc0ac\uc6a9\ubc95\\n\\n```bash\\n## version Update Check\\ncd project-root-path\\nncu\\n```\\n\\n![cexecute_ncu.png](./execute_ncu.png)\\n\\n```bash\\n## version Update\\ncd project-root-path\\nncu -u\\nnpm install\\n```\\n\\n![execute_ncu_u.png](./execute_ncu_u.png)"}]}}')}}]);